function due(e,d){if(e.type!=='habit'||e.archived||d<e.created)return false;if(e.days?.length)return e.days.includes(parse(d).getDay());if(e.interval)return gap(d,e.startDate||e.created)%e.interval===0;return true}function isDaily(e){return (!e.interval||+e.interval===1)&&(!e.days?.length||new Set(e.days).size===7)}function todoDate(e){if(e.track==='checklist'&&!done(e,today()))return null;return Object.entries(db.logs[e.id]||{}).filter(([d,v])=>v>=1).map(([d])=>d).sort()[0]||null}function streak(e){let n=0;for(let i=0;i<3660;i++){let d=shift(today(),-i);if(d<e.created)break;if(!due(e,d))continue;if(done(e,d))n++;else if(i)break}return n}function rate(e){let n=0,y=0;for(let i=0;i<30;i++){let d=shift(today(),-i);if(due(e,d)){n++;if(done(e,d))y++}}return n?Math.round(y/n*100):0}
