function applyVisibleOrder(kind,ids){let all=sorted(db.entries.filter(e=>e.type===kind&&!e.archived)),set=new Set(ids),slots=all.map((e,i)=>set.has(e.id)?i:-1).filter(i=>i>=0),items=ids.map(id=>all.find(e=>e.id===id)).filter(Boolean);if(items.length!==slots.length||items.length!==ids.length||set.size!==ids.length)return false;slots.forEach((p,i)=>all[p]=items[i]);all.forEach((e,i)=>e.rank=i);return true}
