function perfectDays(){let first=db.entries.map(e=>e.created).sort()[0]||today(),n=0,span=Math.min(3660,Math.max(0,gap(today(),first)));for(let i=1;i<=span;i++){let d=shift(today(),-i),planned=db.entries.filter(e=>!e.archived&&(e.type==='habit'?due(e,d):e.date===d&&e.created<=d));if(planned.length&&planned.every(e=>e.type==='habit'?done(e,d):!!todoDate(e)&&todoDate(e)<=d))n++}return n}
