function setSub(e,s,d){db.sublogs[e.id]??={};let sd=subDay(e,d);db.sublogs[e.id][sd]??={};db.sublogs[e.id][sd][s]=!db.sublogs[e.id][sd][s];db.logs[e.id]??={};let all=e.subtasks.every(s=>subDone(e,s,d));if(e.type==='todo')db.logs[e.id]={};db.logs[e.id][d]=all?1:0;recordCompletion(e,d);commit()}function toggleAll(e,d){let y=done(e,d);db.logs[e.id]??={};if(e.type==='todo')db.logs[e.id]={};if(e.track==='checklist'){db.sublogs[e.id]??={};let sd=subDay(e,d);db.sublogs[e.id][sd]={};e.subtasks.forEach(s=>db.sublogs[e.id][sd][s.id]=!y)}if(y)delete db.logs[e.id][d];else db.logs[e.id][d]=goal(e);recordCompletion(e,d);commit()}
